  // 5 图表：趋势
  deck.chart({
    kicker: '趋势',
    title: '增长曲线站在我们这边（季环比指数）',
    kind: 'line',
    categories: ['Q1', 'Q2', 'Q3', 'Q4', 'Q5', 'Q6'],
    series: { '本项目': [100, 108, 121, 139, 158, 181] },
