  // 6 对照
  deck.split({
    kicker: '决策对照',
    title: '砍，还是留',
    left: {
      heading: '砍掉',
      items: [
        '短期省下一笔预算',
        '团队清零，重新寻找方向',
        '用户与客户需要重新安顿',
        '增长曲线被主动打断',
      ],
